-- LIMPEZA E TEXTOS DO HUB (projeto do HUB, iwivldvubmsqyzkkdxoy). Cole no SQL Editor e clique Run. Pode rodar mais de uma vez.
-- O que faz, só nos cards (nada mais do site muda):
--  1) tira os repetidos (o "Programa em Grupo" que estava 2x), o card vazio "Materiais", o "Novo material" e as versões antigas
--     do Passaporte, do Guia A1-B2 e do Kit de Frases (a versão com link direto da Kiwify fica, com o texto das antigas);
--  2) separa os dois "Grupo do WhatsApp" (English On Mission x Culture English);
--  3) arruma a categoria do "Diagnósticos e Testes" (virava um filtro enorme) e escreve uma frase clara em cada card grátis e nos produtos, e troca os botões de compra por "Adquirir";
--  4) liga o card do Programa ao checkout (pay.kiwify.com.br/CohRPDI), que estava sem link.
with p as (select '{"grupoeom": {"titulo": "Grupo do WhatsApp · English On Mission", "linha": "Pratique e caminhe junto durante a semana"}, "grupoculture": {"titulo": "Grupo do WhatsApp · Culture English", "linha": "Dicas de séries, filmes e músicas pra praticar"}, "diagtestes": {"setor": "Testes", "linha": "Descubra como você aprende e qual é o seu nível, do A1 ao C2"}, "vlogeuropa": {"linha": "Londres, Paris e Bruxelas, abertos no YouTube"}, "teste": {"linha": "Teste grátis: do A1 ao C2"}, "prisma": {"linha": "Teste grátis: descubra como você aprende melhor"}, "liveterca": {"linha": "Lives abertas: inglês com séries, filmes e música"}, "eom": {"linha": "Devocionais ao vivo em inglês, sábado às 9h"}, "ingi": {"linha": "O método das múltiplas inteligências aplicado ao inglês"}, "k-6e5c54d0-d6dc-11f1-b2c8-cd52a501feab": {"linha": "Inglês para Viagens", "setor": "E-books", "botao": "Adquirir", "meta": "E-book, 9 capítulos, Pagamento único", "modos": ["viagem", "intercambio", "zero"], "sinopse": "O manual pra quem tem viagem marcada e não quer depender de ninguém lá fora. 9 capítulos na ordem da viagem, com vocabulário com imagem, frases, o que você vai ouvir e diálogos reais. Inclui o Kit de Sobrevivência com as 20 frases que salvam qualquer situação."}, "k-98700bf0-d53c-11f1-bd40-b570d8dc84fc": {"titulo": "Guia de Inglês A1 a B2", "linha": "O que estudar em cada etapa", "setor": "Guias", "botao": "Adquirir", "meta": "Guia digital, 20 páginas em PDF, A1 → B2", "modos": ["teste", "zero", "carreira"], "sinopse": "Um mapa claro do A1 ao B2, sem ficar pulando de vídeo em vídeo. Descubra o que estudar em cada fase, organize sua rotina com planos semanais de 30 a 60 minutos e transforme conteúdo em prática real com missões e checklists."}, "k-2148e660-d4b9-11f1-b0a4-6fbb7dc27ca9": {"titulo": "Kit de Frases para Situações Reais", "linha": "Inglês prático, frases prontas pra usar", "setor": "E-books", "botao": "Adquirir", "meta": "Kit, Frases prontas", "modos": ["viagem", "carreira", "zero"], "sinopse": "As frases que você precisa nas situações essenciais do dia a dia, prontas pra usar."}, "k-c5edeb30-d30f-11f1-9322-452f895bcd20": {"linha": "Os 3 segredos pra destravar seu inglês", "setor": "Aulas", "botao": "Adquirir"}, "k-c8de4710-dc54-11f1-9324-39aa1bf06607": {"linha": "O Programa completo, com acompanhamento", "setor": "Programa", "botao": "Adquirir", "meta": "Programa, Em grupo", "link": "https://pay.kiwify.com.br/CohRPDI", "sinopse": "O Programa completo: todas as aulas, todos os materiais e lives com replay. Quem é aluno também pode pedir aula particular com o Gediel (paga à parte)."}}'::jsonb as patches),
base as (select dados from site_config where id = 'hub'),
cards as (
  select c, ord, row_number() over (partition by c->>'id' order by ord) as rn
  from base, jsonb_array_elements(base.dados->'cards') with ordinality as t(c, ord))
update site_config set dados = jsonb_set(dados, '{cards}', (
  select jsonb_agg(c || coalesce((select patches -> (c->>'id') from p), '{}'::jsonb) order by ord)
  from cards
  where rn = 1 and c->>'id' not in ('cmw5dsm4n', 'cmw5er4sj', 'passaporte', 'guiaa1b2', 'kitfrases')))
where id = 'hub';
